<div
    x-data
    x-init="const controller = new AbortController(); const dismiss = () => Livewire.dispatch('capell-welcome-tour::dismiss'); const targetSelector = @js($currentTargetSelector); const chapterKey = @js($currentChapterKey); if (targetSelector && chapterKey) requestAnimationFrame(() => requestAnimationFrame(() => { if (! document.querySelector(targetSelector)) Livewire.dispatch('capell-welcome-tour::complete-chapter', { chapterKey }) })); if (@js($autoStart)) setTimeout(() => Livewire.dispatch('filament-tour::open-tour', { id: 'capell_admin_welcome.dashboard' }), window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 0 : 450); document.addEventListener('click', (event) => { if (event.target.closest('.driver-popover-close-btn')) dismiss() }, { capture: true, signal: controller.signal }); document.addEventListener('keydown', (event) => { if (event.key === 'Escape' && document.body.classList.contains('driver-active')) dismiss() }, { signal: controller.signal }); document.addEventListener('livewire:navigating', () => controller.abort(), { once: true, signal: controller.signal })"
></div>
